"use strict";
import { PositionStatus, ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { useAccountDrawer } from "components/AccountDrawer/MiniPortfolio/hooks";
import { ExpandoRow } from "components/AccountDrawer/MiniPortfolio/ExpandoRow";
import { LiquidityPositionCard, LiquidityPositionCardLoader } from "components/Liquidity/LiquidityPositionCard";
import { getPositionUrl, parseRestPosition } from "components/Liquidity/utils";
import { useAccount } from "hooks/useAccount";
import { useSimpleAbstractPositions } from "hooks/useSimpleAbstractPositions";
import { atom, useAtom } from "jotai";
import { useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { Link } from "react-router-dom";
import { usePendingLPTransactionsChangeListener } from "state/transactions/hooks";
import { useRequestPositionsForSavedPairs } from "state/user/hooks";
import { Flex, StarBorderButton, Text, styled } from "ui/src";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { TransactionSettingsContextProvider } from "uniswap/src/features/transactions/settings/contexts/TransactionSettingsContext";
import { TransactionSettingKey } from "uniswap/src/features/transactions/settings/slice";
import { usePositionVisibilityCheck } from "uniswap/src/features/visibility/hooks/usePositionVisibilityCheck";
const chainFilterAtom = atom(null);
const versionFilterAtom = atom([ProtocolVersion.V4, ProtocolVersion.V3, ProtocolVersion.V2]);
const statusFilterAtom = atom([PositionStatus.IN_RANGE, PositionStatus.OUT_OF_RANGE]);
const PositionsWrapper = styled(Flex, {
  "$platform-web": {
    display: "grid",
    gridTemplateColumns: "1fr 1fr"
  },
  $lg: {
    gridTemplateColumns: "1fr"
  },
  gap: "$gap16"
});
export default function LiquidityPositions() {
  const [chainFilter, setChainFilter] = useAtom(chainFilterAtom);
  const [versionFilter, setVersionFilter] = useAtom(versionFilterAtom);
  const [statusFilter, setStatusFilter] = useAtom(statusFilterAtom);
  const account = useAccount();
  const { address, isConnected } = account;
  const accountDrawer = useAccountDrawer();
  const isPositionVisible = usePositionVisibilityCheck();
  const [showHiddenPositions, setShowHiddenPositions] = useState(false);
  const { data, isPlaceholderData, refetch, isLoading, fetchNextPage, hasNextPage, isFetching } = useSimpleAbstractPositions({
    address,
    chainIds: chainFilter && chainFilter !== null ? [chainFilter] : [UniverseChainId.Mainnet],
    positionStatuses: statusFilter,
    protocolVersions: versionFilter
  });
  const loadedPositions = useMemo(() => {
    return data?.pages.flatMap((positionsResponse) => positionsResponse.positions) || [];
  }, [data]);
  const savedPositions = useRequestPositionsForSavedPairs();
  const isLoadingPositions = !!account.address && (isLoading || !data);
  const combinedPositions = useMemo(() => {
    const directPositions = loadedPositions;
    const parsedSavedPositions = savedPositions.filter((position) => {
      const matchesChain = !chainFilter || position.data?.position?.chainId === chainFilter;
      const matchesStatus = position.data?.position?.status && statusFilter.includes(position.data?.position?.status);
      const matchesVersion = position.data?.position?.protocolVersion && versionFilter.includes(position.data?.position?.protocolVersion);
      return matchesChain && matchesStatus && matchesVersion;
    }).map((p) => p.data?.position).map(parseRestPosition).filter((position) => !!position) ?? [];
    const combined = [...directPositions, ...parsedSavedPositions].reduce((unique, position) => {
      const positionId = `${position.poolId}-${position.tokenId}-${position.chainId}`;
      const exists = unique.some((p) => `${p.poolId}-${p.tokenId}-${p.chainId}` === positionId);
      if (!exists) {
        unique.push(position);
      }
      return unique;
    }, []);
    return combined;
  }, [loadedPositions, savedPositions, chainFilter, statusFilter, versionFilter]);
  const { visiblePositions, hiddenPositions } = useMemo(() => {
    const visiblePositions2 = [];
    const hiddenPositions2 = [];
    combinedPositions.forEach((position) => {
      const isVisible = isPositionVisible({
        poolId: position.poolId,
        tokenId: position.tokenId,
        chainId: position.chainId,
        isFlaggedSpam: position.isHidden
      });
      if (isVisible) {
        visiblePositions2.push(position);
      } else {
        hiddenPositions2.push(position);
      }
    });
    return { visiblePositions: visiblePositions2, hiddenPositions: hiddenPositions2 };
  }, [combinedPositions, isPositionVisible]);
  usePendingLPTransactionsChangeListener(refetch);
  const loadMorePositions = () => {
    if (hasNextPage && !isFetching) {
      fetchNextPage();
    }
  };
  return <TransactionSettingsContextProvider settingKey={TransactionSettingKey.Swap}>
      <Flex mt={"$spacing48"}>
        <Text variant="subheading1">Your positions</Text>
        <Flex mt={"$spacing16"}>
          {!isConnected ? <Flex gap="$gap12" py="$spacing24">
              <Text variant="body2" color="$neutral2">
                Connect your wallet to see your positions
              </Text>
              <StarBorderButton
    onClick={accountDrawer.open}
    as="button"
    className="button-clear"
    speed="3s"
  >
                <Text variant="buttonLabel2" color="$neutral1">
                  Connect wallet
                </Text>
              </StarBorderButton>
            </Flex> : !isLoadingPositions ? <Flex gap={"$gap16"}>
              <HiddenPositions
    showHiddenPositions={showHiddenPositions}
    setShowHiddenPositions={setShowHiddenPositions}
    hiddenPositions={hiddenPositions}
  />
              <PositionsWrapper opacity={isPlaceholderData ? 0.6 : 1}>
                {visiblePositions.map((position) => {
    const hasGauge = !!position.gaugeAddress;
    return <Link
      key={`${position.poolId}-${position.tokenId}-${position.chainId}`}
      style={{ textDecoration: "none" }}
      to={getPositionUrl(position)}
    >
                      <LiquidityPositionCard
      showVisibilityOption
      liquidityPosition={position}
      showMigrateButton
      hasGauge={hasGauge}
    />
                    </Link>;
  })}
              </PositionsWrapper>
            </Flex> : <PositionsWrapper mt={"$spacing24"}>
              {Array.from({ length: 2 }, (_, index) => <LiquidityPositionCardLoader key={index} />)}
            </PositionsWrapper>}
        </Flex>
      </Flex>
    </TransactionSettingsContextProvider>;
}
function HiddenPositions({ showHiddenPositions, setShowHiddenPositions, hiddenPositions }) {
  const { t } = useTranslation();
  return <ExpandoRow
    isExpanded={showHiddenPositions}
    toggle={() => setShowHiddenPositions(!showHiddenPositions)}
    numItems={hiddenPositions.length}
    title={t("common.hidden")}
    enableOverflow
  >
      <PositionsWrapper>
        {hiddenPositions.map((position) => {
    const hasGauge = !!position.gaugeAddress;
    return <Link
      key={`${position.poolId}-${position.tokenId}-${position.chainId}`}
      style={{ textDecoration: "none" }}
      to={getPositionUrl(position)}
    >
              <LiquidityPositionCard showVisibilityOption liquidityPosition={position} isVisible={false} hasGauge={hasGauge} />
            </Link>;
  })}
      </PositionsWrapper>
    </ExpandoRow>;
}
